// Unmodifiable VIEW vs. immutable COPY
List<String> mutable = new ArrayList<>(List.of("a", "b"));
List<String> view = Collections.unmodifiableList(mutable);
List<String> copy = List.copyOf(mutable);

mutable.add("c");
System.out.println(view); // [a, b, c] -- reflects change!
System.out.println(copy); // [a, b] -- independent copy

package practice;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** A roster that hands out either a frozen snapshot or a read-only live view of its names. */
public class Roster {

    private final List<String> names = new ArrayList<>();

    public void add(String name) {
        names.add(name);
    }

    public List<String> snapshot() {
        return List.copyOf(names);
    }

    public List<String> liveView() {
        return Collections.unmodifiableList(names);
    }
}

